# -*- coding: utf-8 -*-
# =============================================================================
# LLM Assistant Model
# =============================================================================
# FILE: third-party/odoo_llm/llm_assistant/models/llm_assistant.py
#
# PURPOSE:
#   This model represents an AI assistant that can be configured with prompts,
#   tools, and knowledge sources. Assistants can be used for chat, RAG,
#   and autonomous agent tasks.
#
# ODOO 19 COMPATIBILITY FIXES:
#   1. Added missing `is_public` field (required by views)
#   2. Replaced `models.Q` with `@api.constrains` for uniqueness
#   3. Removed `auto_join` parameter (deprecated in Odoo 19)
#   4. Changed `ondelete='restrict'` to `'set null'` where appropriate
#   5. Changed `ondelete='restrict'` to `'set null'` where appropriate
#
# =============================================================================

from odoo import _, api, fields, models
from odoo.exceptions import ValidationError


class LLMAssistant(models.Model):
    """
    LLM Assistant.

    An assistant is a configured AI agent that can:
        - Answer questions using RAG (knowledge bases)
        - Execute tools (functions)
        - Use custom prompts and system instructions
        - Be invoked via API or chat interface
    """
    _name = "llm.assistant"
    _description = "LLM Assistant"
    _inherit = ["mail.thread", "mail.activity.mixin"]

    # -------------------------------------------------------------------------
    # 1. BASIC FIELDS
    # -------------------------------------------------------------------------

    name = fields.Char(
        string="Name",
        required=True,
        tracking=True,
        help="The name of the assistant."
    )

    code = fields.Char(
        string="Code",
        required=True,
        tracking=True,
        help="A unique code identifier for the assistant."
    )

    active = fields.Boolean(
        string="Active",
        default=True,
        tracking=True,
        help="Whether this assistant is active."
    )

    # ========================================================================
    # FIX: Added missing field required by views (llm.assistant search view
    # references 'is_public'). Without this field, search_read fails with
    # "Invalid field 'is_public' on 'llm.assistant'".
    # ========================================================================
    is_public = fields.Boolean(
        string="Public",
        default=True,
        tracking=True,
        help="If True, this assistant is publicly available."
    )

    # -------------------------------------------------------------------------
    # 2. SYSTEM AND PROMPT CONFIGURATION
    # -------------------------------------------------------------------------

    system_prompt = fields.Text(
        string="System Prompt",
        tracking=True,
        help="The system prompt that defines the assistant's role and behaviour."
    )

    # ========================================================================
    # FIX: Removed `auto_join=True` parameter because it is no longer supported
    # in Odoo 19. This was causing a deprecation warning.
    # ========================================================================
    prompt_id = fields.Many2one(
        "llm.prompt",
        string="Prompt Template",
        ondelete="restrict",
        tracking=True,
        help="Prompt template to use for generating system prompts."
    )

    response_style = fields.Selection(
        [
            ("concise", "Concise"),
            ("balanced", "Balanced"),
            ("detailed", "Detailed"),
            ("creative", "Creative"),
        ],
        string="Response Style",
        default="balanced",
        tracking=True,
        help="The style of responses generated by the assistant."
    )

    # -------------------------------------------------------------------------
    # 3. KNOWLEDGE AND TOOLS
    # -------------------------------------------------------------------------

    knowledge_collection_ids = fields.Many2many(
        "llm.knowledge.collection",
        string="Knowledge Collections",
        help="Knowledge collections that this assistant can use for RAG."
    )

    tool_ids = fields.Many2many(
        "llm.tool",
        string="Tools",
        help="Tools that this assistant can execute."
    )

    # -------------------------------------------------------------------------
    # 4. MODEL CONFIGURATION
    # -------------------------------------------------------------------------

    model_id = fields.Many2one(
        "llm.model",
        string="Model",
        ondelete="set null",          # Changed from 'restrict' for compatibility
        tracking=True,
        help="The LLM model to use for this assistant."
    )

    # ========================================================================
    # FIX: Added missing `provider_id` field (required by views)
    # ========================================================================
    
    provider_id = fields.Many2one(
        "llm.provider",
        string="LLM Provider",
        ondelete="set null",
        tracking=True,
        help="The LLM provider that hosts the model."
    )

    temperature = fields.Float(
        string="Temperature",
        default=0.7,
        tracking=True,
        help="Sampling temperature (0.0 to 1.0)."
    )

    max_tokens = fields.Integer(
        string="Max Tokens",
        default=2048,
        tracking=True,
        help="Maximum tokens to generate."
    )

    # -------------------------------------------------------------------------
    # 5. METADATA
    # -------------------------------------------------------------------------

    description = fields.Text(
        string="Description",
        tracking=True,
        help="A human-readable description of the assistant."
    )

    icon = fields.Binary(
        string="Icon",
        attachment=True,
        help="An icon for the assistant."
    )

    # -------------------------------------------------------------------------
    # 6. CONSTRAINTS (Odoo 19 compatible)
    # -------------------------------------------------------------------------

    @api.constrains('code')
    def _check_unique_code(self):
        """
        Ensure that the assistant code is unique.

        This is the Odoo 19‑compatible version of the constraint.
        It replaces the old _sql_constraints approach (which used models.Q)
        that caused an AttributeError.
        """
        for record in self:
            existing = self.search_count([
                ('code', '=', record.code)
            ])
            if existing > 1:
                raise ValidationError(
                    _("Assistant code must be unique.")
                )

    # -------------------------------------------------------------------------
    # 7. HELPER METHODS
    # -------------------------------------------------------------------------

    def invoke(self, message, context=None):
        """
        Invoke the assistant with a message.

        Args:
            message (str): The user message.
            context (dict): Optional context for the assistant.

        Returns:
            str: The assistant's response.

        Raises:
            UserError: If the assistant is not configured correctly.
        """
        from odoo.exceptions import UserError

        if not self.model_id:
            raise UserError(_("No model configured for this assistant."))

        # In a real implementation, this would call the LLM provider
        # with the assistant's configuration (system prompt, tools, etc.)
        #
        # Example:
        # provider = self.model_id.provider_id
        # response = provider.generate(
        #     system_prompt=self.system_prompt,
        #     message=message,
        #     temperature=self.temperature,
        #     max_tokens=self.max_tokens,
        #     context=context
        # )
        # return response

        return _("Assistant invoked with message: {}").format(message)

    def get_system_prompt(self):
        """
        Get the effective system prompt for this assistant.

        Returns:
            str: The combined system prompt.
        """
        if self.prompt_id:
            # Use the prompt template if available
            return self.prompt_id.render(
                assistant_name=self.name,
                response_style=self.response_style,
                description=self.description
            )
        return self.system_prompt or "You are a helpful assistant."

    def get_knowledge_context(self):
        """
        Get the knowledge context for this assistant.

        Returns:
            list: A list of knowledge chunks from the configured collections.
        """
        chunks = self.env["llm.knowledge.chunk"]
        for collection in self.knowledge_collection_ids:
            chunks |= collection.chunk_ids
        return chunks

    def get_tools(self):
        """
        Get the tools configured for this assistant.

        Returns:
            list: A list of tool definitions.
        """
        return self.tool_ids